"""krun job: BEAM + cross-encoder rerank on GPU.

Retrieval-only BEAM was measured locally (MiniLM, no CE): ALL cover@10 was
0.451 / 0.416 / 0.237 at 100K / 500K / 1M. On LongMemEval the same CE lifts
pre-CE 0.894 to 0.958, so BEAM's floor is not BEAM's score. This job adds
BAAI/bge-reranker-v2-m3 over the same candidate band and reports the delta.

beam_probe.py is embedded rather than pulled from the remote, so this runs the
exact local file that produced the floor numbers, with no push required.

  krun benchmarks/kaggle_beam_ce.py --acc NvidiaTeslaT4
"""
import base64, json, os, subprocess, sys, time

WORK = '/kaggle/working'
REPO = f'{WORK}/mnemonics'
RESULTS = f'{WORK}/results'
CE_MODEL = 'BAAI/bge-reranker-v2-m3'
os.makedirs(RESULTS, exist_ok=True)

PKG_B64 = ""

PROBE_B64 = ""


def retry(fn, what, tries=3, wait=8):
    for i in range(1, tries + 1):
        try:
            return fn()
        except Exception as e:
            print(f'[retry {i}/{tries}] {what} basarisiz: {e}', flush=True)
            if i < tries:
                time.sleep(wait * i)
            else:
                raise


def clone():
    subprocess.run(['rm', '-rf', REPO], check=False)
    subprocess.run(['git', 'clone', '--depth', '1',
                    'https://github.com/nakata-app/mnemonics.git', REPO], check=True)


retry(clone, 'git clone')
subprocess.run(['git', '-C', REPO, 'log', '--oneline', '-2'])

retry(lambda: subprocess.run(
    [sys.executable, '-m', 'pip', 'install', '-q', '-e', REPO,
     'sentence-transformers', 'numpy', 'pyarrow', 'huggingface_hub'], check=True),
    'pip install')
print('Install OK', flush=True)

# Local HEAD is ahead of the remote (unpushed dedup commit touching ingest),
# so overwrite the cloned package with the exact tree that produced the local
# floor numbers. Without this the CE delta would be measured against different
# ingest code and would not be comparable.
pkg_tgz = f'{WORK}/pkg.tgz'
with open(pkg_tgz, 'wb') as f:
    f.write(base64.b64decode(PKG_B64))
subprocess.run(['rm', '-rf', f'{REPO}/mnemonics'], check=True)
subprocess.run(['tar', 'xzf', pkg_tgz, '-C', REPO], check=True)
print('package overwritten from embedded tree', flush=True)
subprocess.run([sys.executable, '-c',
                'import mnemonics,sys;print("mnemonics from",mnemonics.__file__)'],
               cwd=REPO, check=True)

probe = f'{REPO}/benchmarks/beam_probe.py'
with open(probe, 'wb') as f:
    f.write(base64.b64decode(PROBE_B64))
print(f'probe written: {os.path.getsize(probe)} bytes', flush=True)

import torch
print('cuda:', torch.cuda.is_available(),
      torch.cuda.get_device_name(0) if torch.cuda.is_available() else '', flush=True)

env = os.environ.copy()
env['PYTHONUNBUFFERED'] = '1'
env['MNEMONICS_RERANK_MODEL'] = CE_MODEL
env['MNEMONICS_DETERMINISTIC'] = '1'
env['MNEMONICS_RERANK_MAX_LENGTH'] = '512'
env['MNEMONICS_RERANK_BATCH_SIZE'] = '8'
env['PYTORCH_ALLOC_CONF'] = 'expandable_segments:True'


def stage(sizes, limit, tag, rerank):
    out = f'{RESULTS}/{tag}'
    cmd = [sys.executable, '-u', 'benchmarks/beam_probe.py',
           '--sizes', sizes, '--top-ks', '5,10,20,50', '--out-dir', out]
    if limit:
        cmd += ['--limit', str(limit)]
    if rerank:
        cmd.append('--rerank')
    print(f'\n=== {tag} sizes={sizes} limit={limit or "all"} '
          f'rerank={rerank} ===', flush=True)
    r = subprocess.run(cmd, cwd=REPO, env=env)
    print(f'{tag} returncode={r.returncode}', flush=True)
    return r.returncode == 0


# Smoke first: 2 conversations with the CE. If the CE path is broken, stop
# before burning the session on 105 conversations.
if not stage('100K', 2, 'smoke_ce', True):
    print('SMOKE FAILED — durduruldu.', flush=True)
    sys.exit(1)
print('SMOKE OK', flush=True)

# Each tier written the moment it finishes, so a 1M timeout keeps 100K/500K.
ok = {}
for size in ['100K', '500K', '1M']:
    try:
        ok[size] = stage(size, 0, f'ce_{size}', True)
    except Exception as e:
        print(f'[{size} coktu] {e}', flush=True)
        ok[size] = False

json.dump({'ce_model': CE_MODEL, 'stages': ok},
          open(f'{RESULTS}/beam_ce_summary.json', 'w'), indent=2)
print('\n=== BITTI ===', json.dumps(ok), flush=True)
